53	const ITEM_BASE_PREMIUMS: Record<string, number> = {
54	  sword: 100,
55	  amulet: 60,
56	  staff: 80,
57	  potion: 40,
58	  rune: 25,
59	  moonstone: 25,
60	};
61	const FIRST_INSURANCE_RATE = 0.1;
62	const PROCESSING_FEE = 5;
63	const RUNE_BLOCK_SIZE = 3;
64	const RUNE_BLOCK_PREMIUM = 60;
65	
66	const calculatePolicyBasePremium = (items: QuoteItem[]): number => {
67	  const countsByType = new Map<string, number>();
68	  for (const item of items) {
69	    countsByType.set(item.type, (countsByType.get(item.type) ?? 0) + 1);
70	  }
71	  let total = 0;
72	  for (const [type, count] of countsByType) {
73	    const formsExactlyOneBlock = count === RUNE_BLOCK_SIZE;
74	    total += formsExactlyOneBlock
75	      ? RUNE_BLOCK_PREMIUM
76	      : count * ITEM_BASE_PREMIUMS[type];
77	  }
78	  return total;
79	};
80	
81	const calculateQuotePremium = (items: QuoteItem[]): number => {
82	  const policyBasePremium = calculatePolicyBasePremium(items);
83	  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_RATE;
84	  return Math.ceil(policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE);
85	};
86	
87	export const runScenario = (scenario: Scenario): ScenarioResult => {
88	  const quoteStep = scenario.steps[0] as QuoteStep;
89	  return { results: [{ premium: calculateQuotePremium(quoteStep.items) }] };
90	};
