const countItemsByType = (items: QuoteItem[]): Map<string, number> => {
  const countsByType = new Map<string, number>();
  for (const item of items) {
    countsByType.set(item.type, (countsByType.get(item.type) ?? 0) + 1);
  }
  return countsByType;
};

const premiumForAlikeGroup = (type: string, count: number): number => {
  const formsExactlyOneBlock = count === ALIKE_BLOCK_SIZE;
  return formsExactlyOneBlock
    ? ALIKE_BLOCK_PREMIUM
    : count * ITEM_BASE_PREMIUMS[type];
};

const calculatePolicyBasePremium = (items: QuoteItem[]): number => {
  let total = 0;
  for (const [type, count] of countItemsByType(items)) {
    total += premiumForAlikeGroup(type, count);
  }
  return total;
};
